 void migrateXtream(){if(!prefs.contains("xcUser")&&!prefs.contains("xcPass")&&!prefs.contains("xcAuth"))return;try{String user=prefs.getString("xcUser",""),pass=prefs.getString("xcPass","");if(user.isEmpty()&&prefs.contains("xcAuth")){android.net.Uri old=android.net.Uri.parse("https://localhost/?"+prefs.getString("xcAuth",""));String u=old.getQueryParameter("username"),p=old.getQueryParameter("password");if(u!=null)user=android.net.Uri.encode(u);if(p!=null)pass=android.net.Uri.encode(p);}NasSecrets.save(this,"xtream_account_v1",user,pass);prefs.edit().remove("xcAuth").remove("xcUser").remove("xcPass").commit();}catch(Exception e){/* Keep legacy credentials for migration retry; never discard on encryption failure. */}}
