 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==603){if(result==RESULT_OK&&data!=null&&data.getData()!=null){try{int flags=data.getFlags()&(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION|android.content.Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((flags&android.content.Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new SecurityException();getContentResolver().takePersistableUriPermission(data.getData(),flags);prefs.edit().putString("recordTree",data.getData().toString()).remove("recordNas").remove("recordNasId").apply();Toast.makeText(this,"Папка сохранена",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Не удалось получить постоянный доступ к папке",Toast.LENGTH_LONG).show();}}return;}if(request==601||request==602){if(result==RESULT_OK&&data!=null&&data.getData()!=null){if(request==601){current=null;applyAudioTrim();player.setMediaItem(MediaItem.fromUri(data.getData()));player.prepare();player.play();status.setText("Локальное видео");}else exportRecording(data.getData());}else pendingExport=null;return;}if(request==501||request==502){if(result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){if(request==502)voiceSearch(words.get(0));else voiceCommand(words.get(0));}}return;}if(request==401||request==402){if(result==RESULT_OK&&data!=null&&data.getData()!=null)backupFile(request,data.getData());return;}if(request!=301||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();status.setText("Чтение плейлиста…");new Thread(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Empty file");StringBuilder s=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null){s.append(line).append('\n');if(s.length()>20000000)throw new IOException("File too large");}}String playlist=s.toString();runOnUiThread(()->{if(!playlist.contains("#EXTINF")){status.setText("Неверный формат M3U");return;}savePlaylist(playlist);group="";filter="";onlyFav=false;onlyUhd=false;parse(playlist);render();status.setText("Каналов: "+channels.size());});}catch(Exception e){runOnUiThread(()->status.setText("Не удалось прочитать файл плейлиста"));}}).start();}
