 String attribute(String line,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?:^|\\s)"+java.util.regex.Pattern.quote(key)+"=\"([^\"]*)\"").matcher(line);return m.find()?m.group(1):"";}
 void archive(Channel ch,Epg.Programme p){if(locked(ch)){askPin(()->archiveAllowed(ch,p));return;}archiveAllowed(ch,p);} void archiveAllowed(Channel ch,Epg.Programme p){if(kidsMode()){kidsNotice();return;}long now=System.currentTimeMillis();if(p.start>=now||ch.catchupDays<=0||now-p.start>ch.catchupDays*86400000L){Toast.makeText(this,"Архив недоступен для этой передачи",Toast.LENGTH_LONG).show();return;}String template=ch.catchupSource.isEmpty()?prefs.getString("archiveTemplate_"+prefs.getString("activeSource",""),""):ch.catchupSource;if(template.isEmpty()){archiveSettings();return;}String u=template.replace("{url}",ch.url).replace("{utc}",Long.toString(p.start/1000)).replace("{utcend}",Long.toString(p.end/1000)).replace("{duration}",Long.toString((p.end-p.start)/1000)).replace("{lutc}",Long.toString(now/1000)).replace("{start}",Long.toString(p.start/1000)).replace("{end}",Long.toString(p.end/1000));if(!ch.catchupSource.isEmpty()&&ch.catchup.equals("append"))u=ch.url+u;if(!u.startsWith("http://")&&!u.startsWith("https://")||u.contains("{")){Toast.makeText(this,"Неподдерживаемый формат архива",Toast.LENGTH_LONG).show();return;}closeShift();current=ch;applyAudioTrim();status.setText("Архив • "+p.title);player.setMediaItem(MediaItem.fromUri(u));player.prepare();player.play();}
