 void recoverPlayback(androidx.media3.common.PlaybackException error){if(localShift!=null){returnLive();Toast.makeText(this,"Локальный буфер недоступен",Toast.LENGTH_SHORT).show();return;}retryHandler.removeCallbacksAndMessages(null);int code=error.errorCode;boolean transientError=code==2001||code==2002||code==2000||code==1002;if(activityVisible&&player.getPlayWhenReady()&&prefs.getBoolean("autoReconnect",true)&&((transientError&&retryCount>=4)||code==2004||code==2005)&&switchBackup())return;MediaItem item=player.getCurrentMediaItem();if(!activityVisible||!player.getPlayWhenReady()||!prefs.getBoolean("autoReconnect",true)||!transientError||item==null||retryCount>=4){status.setText("Ошибка воспроизведения: "+error.getErrorCodeName());return;}int attempt=++retryCount;long delay=new long[]{1000,2000,4000,8000}[attempt-1];status.setText("Восстановление соединения "+attempt+"/4…");retryHandler.postDelayed(()->{if(!activityVisible||isDestroyed()||player.getCurrentMediaItem()!=item||!player.getPlayWhenReady())return;player.prepare();player.play();},delay);}
