 void audioDelayMenu(){new AlertDialog.Builder(this).setTitle("Синхронизация звука").setMessage("Если звук опережает изображение, увеличьте задержку. Работает только в режиме PCM. Если звук уже запаздывает, установите 0 мс.").setItems(new String[]{"Общая задержка","Задержка текущего канала","Сбросить поправку канала"},(d,i)->{Channel ch=current;if(i>0&&ch==null){Toast.makeText(this,"Выберите канал",Toast.LENGTH_SHORT).show();return;}String key=i==0?"audioDelayGlobal":audioTrimKey(ch).replace("audioTrim_","audioDelay_");if(i==2){prefs.edit().remove(key).apply();applyAudioTrim();return;}LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(20),dp(10),dp(20),dp(10));TextView value=new TextView(this);SeekBar bar=new SeekBar(this);bar.setMax(25);bar.setProgress(Math.max(0,Math.min(25,prefs.getInt(key,prefs.getInt("audioDelayGlobal",0))/20)));value.setText(bar.getProgress()*20+" мс");panel.addView(value);panel.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean fromUser){value.setText(v*20+" мс");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});new AlertDialog.Builder(this).setTitle(i==0?"Общая задержка звука":ch.name).setView(panel).setPositiveButton("Применить",(x,w)->{prefs.edit().putInt(key,bar.getProgress()*20).apply();applyAudioTrim();}).setNegativeButton("Отмена",null).show();}).show();}
 androidx.media3.common.audio.AudioProcessor[] audioProcessors(){if(!prefs.getBoolean("forceStereo",false))return new androidx.media3.common.audio.AudioProcessor[]{volumeLeveler};androidx.media3.common.audio.ChannelMixingAudioProcessor mix=new androidx.media3.common.audio.ChannelMixingAudioProcessor();for(int n=1;n<=8;n++){if(n==6)mix.putChannelMixingMatrix(new androidx.media3.common.audio.ChannelMixingMatrix(6,2,new float[]{.4f,0,0,.4f,.28f,.28f,.04f,.04f,.28f,0,0,.28f}));else if(n==8)mix.putChannelMixingMatrix(new androidx.media3.common.audio.ChannelMixingMatrix(8,2,new float[]{.32f,0,0,.32f,.23f,.23f,.03f,.03f,.21f,0,0,.21f,.21f,0,0,.21f}));else mix.putChannelMixingMatrix(androidx.media3.common.audio.ChannelMixingMatrix.create(n,n));}return new androidx.media3.common.audio.AudioProcessor[]{mix,volumeLeveler};}
