 void tracks(int type){ArrayList<String> labels=new ArrayList<>();ArrayList<androidx.media3.common.TrackSelectionOverride> overrides=new ArrayList<>();labels.add(tr("Автоматически","Automatic"));overrides.add(null);if(type==androidx.media3.common.C.TRACK_TYPE_TEXT){labels.add(tr("Отключить","Disable"));overrides.add(null);}for(androidx.media3.common.Tracks.Group g:player.getCurrentTracks().getGroups()){if(g.getType()!=type)continue;for(int i=0;i<g.length;i++){if(!g.isTrackSupported(i))continue;androidx.media3.common.Format f=g.getTrackFormat(i);labels.add((f.label==null?tr("Дорожка ","Track ")+(i+1):f.label)+(f.language==null?"":" • "+f.language));overrides.add(new androidx.media3.common.TrackSelectionOverride(g.getMediaTrackGroup(),i));}}new AlertDialog.Builder(this).setItems(labels.toArray(new String[0]),(d,i)->{androidx.media3.common.TrackSelectionParameters.Builder b=player.getTrackSelectionParameters().buildUpon().clearOverridesOfType(type).setTrackTypeDisabled(type,type==androidx.media3.common.C.TRACK_TYPE_TEXT&&i==1);if(overrides.get(i)!=null)b.addOverride(overrides.get(i));player.setTrackSelectionParameters(b.build());}).show();}
 void multiView(){if(kidsMode()){kidsNotice();return;}if(lightMode()){Toast.makeText(this,"Мультиэкран отключён в экономном режиме. Выберите полный режим в настройках.",Toast.LENGTH_LONG).show();return;}if(displayed.size()<2){Toast.makeText(this,"Нужно минимум два канала",Toast.LENGTH_SHORT).show();return;}String[] names=new String[displayed.size()];boolean[] checked=new boolean[names.length];ArrayList<Channel> options=new ArrayList<>(displayed);for(int i=0;i<names.length;i++)names[i]=options.get(i).name;new AlertDialog.Builder(this).setTitle("Выберите 2–4 канала").setMultiChoiceItems(names,checked,(d,i,b)->checked[i]=b).setPositiveButton("Открыть",(d,w)->{ArrayList<Channel> selected=new ArrayList<>();for(int i=0;i<checked.length;i++)if(checked[i])selected.add(options.get(i));if(selected.size()<2||selected.size()>4){Toast.makeText(this,"Выберите от двух до четырёх каналов",Toast.LENGTH_SHORT).show();return;}showMulti(selected);}).setNegativeButton("Отмена",null).show();}
 void showMulti(ArrayList<Channel> selected){for(Channel ch:selected)if(locked(ch)){askPin(()->showMultiAllowed(selected));return;}showMultiAllowed(selected);} void showMultiAllowed(ArrayList<Channel> selected){boolean resume=player.isPlaying();player.pause();ArrayList<ExoPlayer> players=new ArrayList<>();LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);dialog.setContentView(panel);dialog.setOnDismissListener(d->{for(ExoPlayer p:players)p.release();if(resume&&!isFinishing())player.play();});for(int i=0;i<selected.size();i+=2){LinearLayout row=new LinearLayout(this);panel.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int j=i;j<Math.min(i+2,selected.size());j++){Channel ch=selected.get(j);LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);row.addView(tile,new LinearLayout.LayoutParams(0,-1,1));ExoPlayer p=new ExoPlayer.Builder(this).setLoadControl(new androidx.media3.exoplayer.DefaultLoadControl.Builder().setBufferDurationsMs(5000,12000,1000,2000).setTargetBufferBytes(12*1024*1024).setPrioritizeTimeOverSizeThresholds(false).build()).build();players.add(p);PlayerView pv=new PlayerView(this);pv.setUseController(false);pv.setPlayer(p);tile.addView(pv,new LinearLayout.LayoutParams(-1,0,1));Button audio=new Button(this);audio.setText(ch.name+" • Звук");tile.addView(audio);audio.setOnClickListener(v->{for(ExoPlayer other:players)other.setVolume(other==p?1f:0f);});p.setVolume(j==0?1f:0f);p.setMediaItem(MediaItem.fromUri(ch.url));p.prepare();p.play();}}Button close=new Button(this);close.setText("Закрыть мультиэкран");close.setOnClickListener(v->dialog.dismiss());panel.addView(close);dialog.show();dialog.getWindow().setLayout(-1,-1);}
 File recordingDir(){File dir=new File(getFilesDir(),"recordings");dir.mkdirs();return dir;}
 void recordingCommand(String action,String url,String title){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED&&!prefs.getBoolean("recordNotificationAsked",false)){prefs.edit().putBoolean("recordNotificationAsked",true).apply();requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},812);}android.content.Intent intent=new android.content.Intent(this,RecordingService.class).setAction(action);if(url!=null)intent.putExtra("url",url);if(title!=null)intent.putExtra("title",title);try{if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(intent);else startService(intent);}catch(Exception e){Toast.makeText(this,"Не удалось запустить службу записи",Toast.LENGTH_LONG).show();}}
