 void recordingsAllowed(){File[] files=recordingDir().listFiles((dir,name)->name.endsWith(".ts"));if(files==null||files.length==0){Toast.makeText(this,"Нет записей",Toast.LENGTH_SHORT).show();return;}Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));String[] labels=new String[files.length];for(int i=0;i<files.length;i++)labels[i]=(protectedRecording(files[i])?"🔒 ":"")+files[i].getName()+" • "+files[i].length()/1048576+" МБ";new AlertDialog.Builder(this).setTitle("Мои записи").setItems(labels,(d,i)->new AlertDialog.Builder(this).setItems(new String[]{"Воспроизвести","Удалить","Экспорт на накопитель","Экспорт в SMB / NAS",protectedRecording(files[i])?"Снять защиту":"Защитить от удаления"},(x,j)->{if(RecordingService.active){Toast.makeText(this,"Сначала остановите запись",Toast.LENGTH_SHORT).show();return;}if(j==4){toggleRecordingProtection(files[i]);recordings();return;}if(j==1&&protectedRecording(files[i])){Toast.makeText(this,"Сначала снимите защиту записи",Toast.LENGTH_LONG).show();return;}if(j==3){smbDialog(files[i]);return;}if(j==2){chooseExport(files[i]);return;}if(j==0){current=null;applyAudioTrim();player.setMediaItem(MediaItem.fromUri(android.net.Uri.fromFile(files[i])));player.prepare();player.play();status.setText("Запись • "+labels[i]);}else new AlertDialog.Builder(this).setMessage("Удалить запись?").setPositiveButton("Удалить",(q,z)->{if(!protectedRecording(files[i])&&!RecordingService.active)files[i].delete();recordings();}).setNegativeButton("Отмена",null).show();}).show()).show();}
