 void backupFile(int request,android.net.Uri uri){if(request==401){new Thread(()->{try{org.json.JSONObject root=new org.json.JSONObject(),values=new org.json.JSONObject();root.put("version",2);for(Map.Entry<String,?> entry:prefs.getAll().entrySet())if(safeBackupValue(entry.getKey(),entry.getValue()))values.put(entry.getKey(),entry.getValue());root.put("settings",values);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}runOnUiThread(()->status.setText(tr("Настройки сохранены","Settings exported")));}catch(Exception e){runOnUiThread(()->status.setText(tr("Ошибка экспорта","Export failed")));}}).start();return;}new Thread(()->{try{StringBuilder s=new StringBuilder();try(InputStream in=getContentResolver().openInputStream(uri);Reader reader=new InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)){char[] buf=new char[4096];int n;while((n=reader.read(buf))!=-1){s.append(buf,0,n);if(s.length()>1048576)throw new IOException();}}org.json.JSONObject root=new org.json.JSONObject(s.toString());int version=root.getInt("version");if(version!=1&&version!=2)throw new IOException();org.json.JSONObject values=root.getJSONObject("settings");android.content.SharedPreferences.Editor editor=prefs.edit();Iterator<String> keys=values.keys();while(keys.hasNext()){String k=keys.next();Object v=values.get(k);if(!safeBackupValue(k,v))continue;if(v instanceof Boolean)editor.putBoolean(k,(Boolean)v);else if(v instanceof Integer)editor.putInt(k,(Integer)v);else if(v instanceof String)editor.putString(k,(String)v);}if(!editor.commit())throw new IOException();runOnUiThread(()->{if(!isDestroyed())recreate();});}catch(Exception e){runOnUiThread(()->status.setText(tr("Ошибка восстановления","Restore failed")));}}).start();}
